  const Storage = {
    get(key, defaultValue) {
      try {
        const item = localStorage.getItem(key);
        return item ? JSON.parse(item) : defaultValue;
      } catch (err) {
        console.warn(`Error reading localStorage for key "${key}":`, err);
        return defaultValue;
      }
    },
    set(key, value) {
      try {
        localStorage.setItem(key, JSON.stringify(value));
      } catch (err) {
        console.warn(`Error saving to localStorage for key "${key}":`, err);
      }
    },
    remove(key) {
      try {
        localStorage.removeItem(key);
      } catch (err) {
        console.warn(`Error removing from localStorage for key "${key}":`, err);
      }
    }
  };

  // Indian Rupee currency formatter (Intl.NumberFormat)
